import { CURRENCY_DEFAULTS, ICurrencySettings } from '@game-studio/utilities';
import { queryStringParams } from '../services/query-string';

export function getCurrencySettings(): ICurrencySettings {
    const region = queryStringParams.locale;

    switch (region) {
        case 'it-it':
        case 'es-es':
            return { ...CURRENCY_DEFAULTS.EUR, roundOnWholeUnits: true };
        case 'se-se':
            return { ...CURRENCY_DEFAULTS.SEK, roundOnWholeUnits: true };
        case 'dk-dk':
            return { ...CURRENCY_DEFAULTS.DKK, roundOnWholeUnits: true };
        default:
            return { ...CURRENCY_DEFAULTS.GBP, roundOnWholeUnits: true };
    }
}
